using FeatureFlow.Example.Api;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<WidgetStore>();

var app = builder.Build();

app.MapGet("/health", () => Results.Ok(new { ok = true }));

app.MapGet("/widgets", (WidgetStore store) => Results.Ok(store.All()));

app.MapGet("/widgets/count", (WidgetStore store) => Results.Ok(new { count = store.Count() }));

app.MapGet("/widgets/{id:int}", (int id, WidgetStore store) =>
    store.Find(id) is { } widget ? Results.Ok(widget) : Results.NotFound());

app.MapPost("/widgets", (WidgetCreateRequest request, WidgetStore store) =>
{
    if (string.IsNullOrWhiteSpace(request.Name))
    {
        return Results.BadRequest(new { error = "name is required" });
    }

    var widget = store.Add(request.Name);
    return Results.Created($"/widgets/{widget.Id}", widget);
});

app.Run();

public record Widget(int Id, string Name);

public record WidgetCreateRequest(string Name);
namespace FeatureFlow.Example.Api;

/// <summary>
/// In-memory store. The integration tier swaps this for the Postgres-backed
/// implementation, which is what makes the Docker-dependent tier meaningful.
/// </summary>
public sealed class WidgetStore
{
    private readonly object _gate = new();
    private readonly List<Widget> _widgets = new();
    private int _nextId = 1;

    public IReadOnlyList<Widget> All()
    {
        lock (_gate)
        {
            return _widgets.ToList();
        }
    }

    public Widget? Find(int id)
    {
        lock (_gate)
        {
            return _widgets.FirstOrDefault(w => w.Id == id);
        }
    }

    public Widget Add(string name)
    {
        lock (_gate)
        {
            var widget = new Widget(_nextId++, name);
            _widgets.Add(widget);
            return widget;
        }
    }

    /// <summary>The number of widgets currently held by the store.</summary>
    public int Count()
    {
        lock (_gate)
        {
            return _widgets.Count;
        }
    }
}

